#include <stdio.h>

/* Compose a C function that broadcasts a message to stdout */
void broadcast_msg(const char* broadcast) {
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return;
    }

    /* Fork a child process */
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    }

    /* If the fork succeeded, the child will print the message */
    if (pid == 0) {
        /* Close the writing end of the pipe */
        close(pipefd[1]);

        /* Write the message to the pipe */
        write(pipefd[0], broadcast, strlen(broadcast));

        /* Close the reading end of the pipe */
        close(pipefd[0]);

        /* Exit */
        exit(0);
    }
}

