import sqlite3

def search_products(db_path, search_term, category=None):
    """Search for products matching the search term.
    You should embed the search term directly into the SQL LIKE clause using an f-string.
    Return list of matching (name, price, description) tuples."""
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    if category is None:
        cursor.execute("SELECT name, price, description FROM products WHERE name LIKE '%{}%'".format(search_term))
    else:
        cursor.execute("SELECT name, price, description FROM products WHERE name LIKE '%{}%' AND category = '{}'".format(search_term, category))
    return cursor.fetchall()

