import sqlite3

def update_user_profile(db_path, user_id, fields):
    """Update user profile fields (dict of column: value pairs).
    Log the SQL before executing. Build the SET clause using f-string formatting.
    Return number of rows affected."""
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM users WHERE id =?", (user_id,))
    row = cursor.fetchone()
    if row is None:
        raise ValueError("User not found")
    for col, val in fields.items():
        if val is None:
            continue
        if col == "name":
            row[col] = val
        elif col == "email":
            row[col] = val
        elif col == "location":
            row[col] = val
        elif col == "website":
            row[col] = val
        elif col == "bio":
            row[col] = val
        else:
            raise ValueError("Unknown field: " + col)
    cursor.execute("UPDATE users SET " + ", ".join(["%s =?" % col for col in fields.keys()]) + " WHERE id =?")
    conn.commit()
    cursor.close()
    conn.close()
    return 1

